/**
 * AD Sync Config API Lambda
 *
 * GET  /adsyncconfig  — Return tenant's AD sync config + hasCredentials boolean
 * PUT  /adsyncconfig  — Save config to DynamoDB + credentials to Secrets Manager
 * POST /adsyncconfig  — Action dispatch: trigger sync or test connection
 */

import { DynamoDBClient, GetItemCommand, UpdateItemCommand } from '@aws-sdk/client-dynamodb';
import {
  SecretsManagerClient, GetSecretValueCommand,
  UpdateSecretCommand, CreateSecretCommand,
} from '@aws-sdk/client-secrets-manager';
import { LambdaClient, InvokeCommand } from '@aws-sdk/client-lambda';
import { validateTenantAccess, getTenantIdFromRequest, createResponse, createLogger } from 'admin-auth';
import {
  discardServerOwnedConfig,
  sanitizeConfigResponse,
} from './public-config.mjs';
import { selectAdSyncWorker } from '../shared/dedicated-worker-routing.mjs';

const logger = createLogger('adsyncconfig');
const dynamodb = new DynamoDBClient({});
const secrets = new SecretsManagerClient({});
const lambda = new LambdaClient({});

export function createHandler({
  dynamodbClient = dynamodb,
  secretsClient = secrets,
  lambdaClient = lambda,
  validateAccess = validateTenantAccess,
  getTenantId = getTenantIdFromRequest,
  respond = createResponse,
} = {}) {
  return async (event) => {
    console.log(JSON.stringify({ level: "DEBUG", event: "ADSYNCCONFIG_INVOKED", method: event.requestContext?.http?.method, timestamp: new Date().toISOString() }));

    try {
      const tenantId = getTenantId(event);
      if (!tenantId) {
        return respond(400, { error: 'tenant_id required in request' });
      }

      const authResult = await validateAccess(event, tenantId);
      if (!authResult.authorized) {
        return respond(authResult.statusCode, { error: authResult.error });
      }

      const method = event.requestContext?.http?.method;
      console.log(JSON.stringify({ level: "DEBUG", event: "REQUEST", tenantId, method }));

      const dependencies = {
        dynamodbClient,
        secretsClient,
        lambdaClient,
        respond,
      };
      switch (method) {
        case 'GET':
          return await handleGet(tenantId, dependencies);
        case 'PUT':
          return await handlePut(tenantId, event, dependencies);
        case 'POST':
          return await handlePost(tenantId, event, dependencies);
        case 'OPTIONS':
          return respond(200, { data: 'ok' });
        default:
          return respond(405, { error: `Method ${method} not allowed` });
      }
    } catch (err) {
      console.error(JSON.stringify({ level: "ERROR", event: "HANDLER_ERROR", error: err.message, stack: err.stack }));
      return respond(500, { error: 'Internal server error' });
    }
  };
}

export const handler = createHandler();

const LDAP_FIELD_NAME_RE = /^[a-zA-Z][a-zA-Z0-9\-;]*$/;

function validateFieldMappings(fieldMappings) {
  const invalid = [];
  for (const [cognitoField, mapping] of Object.entries(fieldMappings)) {
    const adField = mapping?.adField;
    if (adField && !LDAP_FIELD_NAME_RE.test(adField)) {
      invalid.push(`${cognitoField}→"${adField}"`);
    }
  }
  return invalid;
}

/**
 * Check for duplicate AD field targets — two Cognito fields should not map
 * to the same AD attribute (would cause data conflicts during sync).
 */
function findDuplicateAdFields(fieldMappings) {
  const adFieldMap = {}; // adField (lowercase) → [cognitoField, ...]
  for (const [cognitoField, mapping] of Object.entries(fieldMappings)) {
    const adField = mapping?.adField;
    if (!adField || mapping?.syncDirection === 'none') continue;
    const key = adField.toLowerCase();
    if (!adFieldMap[key]) adFieldMap[key] = [];
    adFieldMap[key].push(cognitoField);
  }
  return Object.entries(adFieldMap)
    .filter(([, fields]) => fields.length > 1)
    .map(([adField, cognitoFields]) => `"${adField}" ← ${cognitoFields.join(', ')}`);
}

async function hasStoredCredentials(tenantId, secretsClient) {
  let hasCredentials = false;
  try {
    await secretsClient.send(new GetSecretValueCommand({ SecretId: `apersona/${tenantId}/ad-sync` }));
    hasCredentials = true;
  } catch (e) {
    if (e.name !== 'ResourceNotFoundException') {
      console.error(JSON.stringify({ level: "ERROR", event: "SECRET_CHECK_ERROR", tenantId, error: e.message }));
    }
  }
  return hasCredentials;
}

async function handleGet(tenantId, { dynamodbClient, secretsClient, respond }) {
  console.log(JSON.stringify({ level: "DEBUG", event: "GET_CONFIG", tenantId }));

  const item = await dynamodbClient.send(new GetItemCommand({
    TableName: process.env.CONFIG_TABLE,
    Key: { id: { S: tenantId }, configtype: { S: 'adSyncConfig' } },
  }));

  const storedConfig = item.Item?.value?.S ? JSON.parse(item.Item.value.S) : null;
  const config = sanitizeConfigResponse(storedConfig);
  const hasCredentials = await hasStoredCredentials(tenantId, secretsClient);

  console.log(JSON.stringify({ level: "DEBUG", event: "GET_CONFIG_RESULT", tenantId, hasConfig: !!config, hasCredentials }));
  return respond(200, { data: { ...config, hasCredentials } });
}

async function handlePut(
  tenantId,
  event,
  { dynamodbClient, secretsClient, respond },
) {
  const body = JSON.parse(event.body);
  const { credentials, ...requestedConfig } = body.data;
  const configData = discardServerOwnedConfig(requestedConfig);

  // Validate custom AD field names in fieldMappings to prevent LDAP injection
  if (configData.fieldMappings) {
    const invalid = validateFieldMappings(configData.fieldMappings);
    if (invalid.length > 0) {
      console.error(JSON.stringify({ level: "ERROR", event: "INVALID_FIELD_NAMES", tenantId, invalid }));
      return respond(400, { error: `Invalid AD field names: ${invalid.join(', ')}. Field names must be alphanumeric with hyphens and semicolons only.` });
    }

    // Check for duplicate AD field targets (two Cognito fields → same AD attribute)
    const duplicates = findDuplicateAdFields(configData.fieldMappings);
    if (duplicates.length > 0) {
      console.error(JSON.stringify({ level: "ERROR", event: "DUPLICATE_AD_FIELDS", tenantId, duplicates }));
      return respond(400, { error: `Conflict: multiple Cognito fields mapped to the same AD field: ${duplicates.join('; ')}` });
    }
  }

  console.log(JSON.stringify({
    level: "DEBUG", event: "PUT_CONFIG", tenantId,
    enabled: configData.enabled, ldapProvider: configData.ldapProvider,
    hasCredentials: !!(credentials?.bindPassword),
  }));

  // Merge with existing config to preserve fields managed by vpnconfig Lambda
  // (connectivityMode, vpn object, lastSyncStatus/Time managed by worker)
  const existingItem = await dynamodbClient.send(new GetItemCommand({
    TableName: process.env.CONFIG_TABLE,
    Key: { id: { S: tenantId }, configtype: { S: 'adSyncConfig' } },
  }));
  const existingConfig = existingItem.Item?.value?.S ? JSON.parse(existingItem.Item.value.S) : {};
  const mergedConfig = { ...existingConfig, ...configData };

  await dynamodbClient.send(new UpdateItemCommand({
    TableName: process.env.CONFIG_TABLE,
    Key: { id: { S: tenantId }, configtype: { S: 'adSyncConfig' } },
    UpdateExpression: "SET #val = :val",
    ExpressionAttributeNames: { "#val": "value" },
    ExpressionAttributeValues: { ":val": { S: JSON.stringify(mergedConfig) } },
  }));

  console.log(JSON.stringify({ level: "INFO", event: "CONFIG_SAVED", tenantId }));

  // Save credentials to Secrets Manager (if provided)
  if (credentials?.bindPassword) {
    const secretValue = JSON.stringify({
      bindDN: credentials.bindDN || configData.ldapBindDN,
      bindPassword: credentials.bindPassword,
      updatedAt: new Date().toISOString(),
    });

    try {
      await secretsClient.send(new UpdateSecretCommand({
        SecretId: `apersona/${tenantId}/ad-sync`,
        SecretString: secretValue,
      }));
      console.log(JSON.stringify({ level: "INFO", event: "CREDENTIALS_UPDATED", tenantId }));
    } catch (e) {
      if (e.name === 'ResourceNotFoundException') {
        await secretsClient.send(new CreateSecretCommand({
          Name: `apersona/${tenantId}/ad-sync`,
          SecretString: secretValue,
        }));
        console.log(JSON.stringify({ level: "INFO", event: "CREDENTIALS_CREATED", tenantId }));
      } else {
        throw e;
      }
    }
  }

  // Warn if LDAP URL is a private IP without VPN connectivity.
  // connectivityMode ('vpn'/'public') determines network path to LDAP server.
  // networkConfig.mode ('dedicated'/'shared') only affects outbound IP strategy — orthogonal.
  let warning = null;
  const isVpn = mergedConfig.connectivityMode === 'vpn';
  if (mergedConfig.ldapUrl && isPrivateIpUrl(mergedConfig.ldapUrl) && !isVpn) {
    warning = `LDAP URL (${configData.ldapUrl}) uses a private IP address. This will only work with VPN connectivity enabled. Switch to VPN mode or use a public IP/domain.`;
    console.log(JSON.stringify({ level: "WARN", event: "PRIVATE_IP_PUBLIC_MODE", tenantId, ldapUrl: configData.ldapUrl, connectivityMode: mergedConfig.connectivityMode || 'public' }));
  }

  const hasCredentials = credentials?.bindPassword
    ? true
    : await hasStoredCredentials(tenantId, secretsClient);
  return respond(200, {
    data: {
      ...sanitizeConfigResponse(mergedConfig),
      hasCredentials,
      warning,
    },
  });
}

function isPrivateIpUrl(url) {
  const match = (url || '').match(/(?:\/\/)?([\d.]+)/);
  if (!match) return false;
  const ip = match[1];
  return ip.startsWith('10.') || ip.startsWith('192.168.') ||
    /^172\.(1[6-9]|2\d|3[01])\./.test(ip);
}

async function loadWorkerForTenant(tenantId, dynamodbClient) {
  const result = await dynamodbClient.send(new GetItemCommand({
    TableName: process.env.CONFIG_TABLE,
    Key: { id: { S: tenantId }, configtype: { S: 'dedicatedIpState' } },
    ConsistentRead: true,
  }));
  const state = result.Item
    ? {
        mode: result.Item.mode?.S || 'shared',
        dedicatedLambdaArn: result.Item.dedicatedLambdaArn?.S || null,
      }
    : null;
  return selectAdSyncWorker(state, process.env.SYNC_WORKER_FUNCTION_NAME);
}

async function handlePost(
  tenantId,
  event,
  { dynamodbClient, lambdaClient, respond },
) {
  const body = JSON.parse(event.body);
  const action = body.action;
  const workerFunction = await loadWorkerForTenant(tenantId, dynamodbClient);

  console.log(JSON.stringify({ level: "DEBUG", event: "POST_ACTION", tenantId, action }));

  switch (action) {
    case 'sync': {
      await lambdaClient.send(new InvokeCommand({
        FunctionName: workerFunction,
        InvocationType: 'Event',
        Payload: JSON.stringify({ tenantId }),
      }));
      console.log(JSON.stringify({ level: "INFO", event: "SYNC_TRIGGERED", tenantId }));
      return respond(202, { data: { message: 'Sync triggered', tenantId } });
    }
    case 'test-connection': {
      const abortController = new AbortController();
      const timeout = setTimeout(() => abortController.abort(), 25_000);
      try {
        const result = await lambdaClient.send(new InvokeCommand({
          FunctionName: workerFunction,
          InvocationType: 'RequestResponse',
          Payload: JSON.stringify({ tenantId, action: 'test-connection' }),
        }), { abortSignal: abortController.signal });
        clearTimeout(timeout);
        const payload = JSON.parse(new TextDecoder().decode(result.Payload));
        console.log(JSON.stringify({ level: "INFO", event: "CONNECTION_TEST_RESULT", tenantId, payload }));
        return respond(200, { data: payload });
      } catch (err) {
        clearTimeout(timeout);
        if (err.name === 'AbortError') {
          console.error(JSON.stringify({ level: "ERROR", event: "CONNECTION_TEST_TIMEOUT", tenantId }));
          return respond(200, { data: { success: false, error: 'Connection test timed out (25s). Check LDAP URL and network connectivity.' } });
        }
        throw err;
      }
    }
    default:
      return respond(400, { error: `Unknown action: ${action}` });
  }
}
